// LookupField returns the FieldSpec for k, or false when k is not a profile field.
func LookupField(k Key) (FieldSpec, bool) {
	for _, spec := range FieldSpecs() {
		if spec.Key == k {
			return spec, true
		}
	}
	return FieldSpec{}, false
}

// SafetyFloorSpec describes one safety-floor invariant declared in schema/profile.toml.
type SafetyFloorSpec struct {
	Key              Key
	Rule             SafetyRule
	HasRequiredValue bool
	RequiredValue    any
	What             string
	Why              string
	Risk             string
	Undo             string
}

// SafetyFloorSpecs returns a fresh slice of every safety-floor rule.
func SafetyFloorSpecs() []SafetyFloorSpec {
	return []SafetyFloorSpec{
		{
			Key:  KeySafetyBackups,
			Rule: RuleSafetyFloorBackups,
			What: "Mandatory pre-mutation file and state backups.",
			Why:  "Every mutation must capture a durable backup manifest before touching the host.",
			Risk: "Disabling backups would make failed or interrupted applies unrecoverable.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:  KeySafetyUndo,
			Rule: RuleSafetyFloorUndo,
			What: "Mandatory revert and undo support for every kit-managed unit.",
			Why:  "Operators must be able to return to a prior stable point or baseline.",
			Risk: "Disabling undo breaks the kit's reversibility guarantee.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:  KeySafetyDeadManTimer,
			Rule: RuleSafetyFloorDeadManTimer,
			What: "Mandatory dead-man rollback timer for remote SSH and firewall mutations.",
			Why:  "Protects against remote lockout when firewall or SSH settings change.",
			Risk: "Disabling the dead-man timer can permanently lock operators out of remote hosts.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:  KeySafetySecretHandling,
			Rule: RuleSafetyFloorSecretHandling,
			What: "Mandatory secret exclusion from config, logs and terminal output.",
			Why:  "Desired-state profiles and logs must never store or leak credentials.",
			Risk: "Relaxing secret handling exposes tokens, keys and recovery material.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:  KeySafetyRootApprovalPhrase,
			Rule: RuleSafetyFloorRootApproval,
			What: "Mandatory typed plan-digest approval phrase for privileged applies.",
			Why:  "Ensures a human reviewed the exact staged plan before root execution.",
			Risk: "Bypassing the approval phrase allows unreviewed privileged host changes.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:  KeySafetyStagedRootBinary,
			Rule: RuleSafetyFloorStagedRoot,
			What: "Mandatory execution of root steps from the root-owned staged binary path.",
			Why:  "Prevents privilege escalation through a user-writable checkout.",
			Risk: "Running root steps from an unstaged path allows local tampering.",
			Undo: "Not configurable; always enforced.",
		},
		{
			Key:              KeySecurityDiskEncryptionRequired,
			Rule:             RuleSafetyFloorDiskEncryption,
			HasRequiredValue: true,
			RequiredValue:    true,
			What:             "Require full-disk encryption (LUKS on Linux, FileVault on macOS).",
			Why:              "Protects local repositories, caches and credentials at rest.",
			Risk:             "Disabling disk encryption exposes workstation data if hardware is lost or stolen.",
			Undo:             "Not weaken-able; must remain true.",
		},
		{
			Key:              KeySecuritySecureBootRequired,
			Rule:             RuleSafetyFloorSecureBoot,
			HasRequiredValue: true,
			RequiredValue:    true,
			What:             "Require verified boot integrity (Secure Boot on Linux, Apple Silicon boot security on macOS).",
			Why:              "Prevents unsigned kernel or boot-chain tampering.",
			Risk:             "Disabling verified boot weakens tamper resistance of the host.",
			Undo:             "Not weaken-able; must remain true.",
		},
		{
			Key:              KeySecurityRemoteScope,
			Rule:             RuleSafetyFloorRemoteScope,
			HasRequiredValue: true,
			RequiredValue:    "tailscale-only",
			What:             "Restrict remote access strictly to the mesh VPN interface.",
			Why:              "Keeps SSH and remote desktop off LAN and public interfaces.",
			Risk:             "Broadening remote_scope exposes administrative listeners outside the tailnet.",
			Undo:             "Not weaken-able; must remain tailscale-only.",
		},
		{
			Key:              KeyToolingInstallAgents,
			Rule:             RuleSafetyFloorRequiredAgents,
			HasRequiredValue: true,
			RequiredValue:    true,
			What:             "Install the required baseline AI coding agent CLIs.",
			Why:              "Every agent workstation profile includes the baseline agent harness set.",
			Risk:             "Turning off install_agents breaks the workstation baseline contract.",
			Undo:             "Not weaken-able; must remain true.",
		},
	}
}

// LookupSafetyFloor returns the SafetyFloorSpec for k, or false when k has no floor rule.
func LookupSafetyFloor(k Key) (SafetyFloorSpec, bool) {
	for _, spec := range SafetyFloorSpecs() {
		if spec.Key == k {
			return spec, true
		}
	}
	return SafetyFloorSpec{}, false
}

// Profile is the typed representation of a Schema 3 machine profile.
type Profile struct {
	SchemaVersion int64               `toml:"schema_version" json:"schema_version"`
	Profile       ProfileKind         `toml:"profile" json:"profile"`
	State         ProfileState        `toml:"state" json:"state"`
	Deployment    DeploymentConfig    `toml:"deployment" json:"deployment"`
	Machine       MachineConfig       `toml:"machine" json:"machine"`
	Accounts      AccountsConfig      `toml:"accounts" json:"accounts"`
	Remote        RemoteConfig        `toml:"remote" json:"remote"`
	Tooling       ToolingConfig       `toml:"tooling" json:"tooling"`
	SourceControl SourceControlConfig `toml:"source_control" json:"source_control"`
	Collaboration CollaborationConfig `toml:"collaboration" json:"collaboration"`
	ModelAuth     ModelAuthConfig     `toml:"model_auth" json:"model_auth"`
	Security      SecurityConfig      `toml:"security" json:"security"`
	Resources     ResourcesConfig     `toml:"resources" json:"resources"`
	Backup        BackupConfig        `toml:"backup" json:"backup"`
	Maintenance   MaintenanceConfig   `toml:"maintenance" json:"maintenance"`
}

// DeploymentConfig holds the [deployment] table of a Schema 3 machine profile.
type DeploymentConfig struct {
	Namespace string      `toml:"namespace" json:"namespace"`
	Context   ProfileKind `toml:"context" json:"context"`
	Ownership Ownership   `toml:"ownership" json:"ownership"`
}

